/**
 * Write `src/ui/strings.ts` from `docs/chat-ui/strings.json`.
 *
 * The JSON is the table shared word for word with the iOS and Android SDKs; the TypeScript module is
 * how the web ships it — typed keys, and no JSON import for a bundler to be configured for. Run this
 * after the shared table changes. `test/ui-strings.test.ts` fails if the two have drifted apart.
 */
import { readFile, writeFile } from 'node:fs/promises';

const table = JSON.parse(
  await readFile(new URL('../docs/chat-ui/strings.json', import.meta.url), 'utf8'),
);

const lines = [
  '// Generated by scripts/strings.mjs from docs/chat-ui/strings.json. Do not edit by hand: change the',
  '// shared table and run `node scripts/strings.mjs`.',
  '',
  '/**',
  ' * Every word the chat interface says, in English and Arabic — the hosted widget’s own table, with',
  ' * the same keys on every platform. `{name}` marks where a value goes; nothing here is ever HTML.',
  ' */',
  'export const CNCT_STRINGS = {',
];
for (const language of ['en', 'ar']) {
  lines.push(`  ${language}: {`);
  for (const [key, value] of Object.entries(table[language])) {
    lines.push(`    ${key}: ${JSON.stringify(value)},`);
  }
  lines.push('  },');
}
lines.push('} as const;', '');
lines.push('/** The name of one of the interface’s words. */');
lines.push("export type CnctStringKey = keyof (typeof CNCT_STRINGS)['en'];", '');

await writeFile(new URL('../src/ui/strings.ts', import.meta.url), lines.join('\n'), 'utf8');
console.log(`src/ui/strings.ts — ${Object.keys(table.en).length} keys`);
